        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record(ClaimAudit.line("CLAIM_EDITED", claim, by, person == null ? "" : person.getName()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.ConflictException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/** Refuses a save of a claim whose editor another user holds open. */
public class RefuseLockedClaim {
    public void check(@Val Claim claim, @Val ChangedBy by, ClaimLockRepository locks) throws ConflictException {
        String holder = locks.holder(claim.getId());
        if (holder != null && !holder.equals(by.name())) {
            throw new ConflictException(ApplyClaimLock.locked(holder));
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Val;

/** Only a DRAFT claim may be edited; to change an open claim, void it and add a new one. */
public class RefuseNonDraftEdit {
    public void check(@Val Claim claim) throws BadRequestException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new BadRequestException("Only a DRAFT claim can be edited; void it and add a new one instead");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses any change to a claim belonging to a closed period: one whose due-by falls inside it. */
public class RefuseClosedClaim {
    public void check(@Val Claim claim, PeriodRepository periods) throws BadRequestException {
        if (periods.closedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new BadRequestException(RefuseClosedDate.CLOSED);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.session.ChangedBy;

/**
 * A claim's audit record: the event, sheet, user, then person, amount (two decimals) and date, and
 * the claim's number when it has one.
 */
final class ClaimAudit {

    private ClaimAudit() {
    }

    static String line(String event, Claim claim, ChangedBy by, String personName) {
        return line(event, claim, by, personName, claim.getNumber());
    }

    /** The CLAIM_ADDED record: the claim's line, then its reference and its tags when it has them. */
    static String added(Claim claim, ChangedBy by, String personName) {
        return line("CLAIM_ADDED", claim, by, personName) + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags());
    }

    static String line(String event, Claim claim, ChangedBy by, String personName, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + by.name() + " person=" + personName + " amount="
                + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
